<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import {useRoute} from 'vue-router';
import {api} from '../api/client';
import {bindingsApi,type GenerationRun} from '../api/bindings';
type RunStep=NonNullable<GenerationRun['steps']>[number];
import {useShotWorkspace} from '../composables/useShotWorkspace';
import GenerationRunStages from '../components/studio/GenerationRunStages.vue';
import ShotPreview from '../components/studio/ShotPreview.vue';
const {projectId,draftId,sceneId,base,draft,error,reload}=useShotWorkspace();
const runId=String(useRoute().params.runId),run=ref<GenerationRun>(),busy=ref(false),message=ref('');let alive=true,timer:ReturnType<typeof setInterval>|undefined,inFlight=false;
const steps=computed(()=>run.value?.steps||[]);
const takes=computed(()=>draft.value?.media_takes?.filter(t=>run.value?.task_ids.includes(t.task_id))||[]);
const versions=computed(()=>draft.value?.video_versions?.filter(v=>run.value?.task_ids.includes(v.task_id))||[]);
const snapshot=computed(()=>run.value?.plan?.[0]);
const directVideo=computed(()=>snapshot.value?.path==='reference_video');
const statusLabels:Record<string,string>={queued:'排队中',running:'生成中',succeeded:'已完成',failed:'失败',cancelled:'已取消'};
const kindLabels:Record<string,string>={image:'分镜图',video:'视频',speech:'配音'};
async function refresh(){if(inFlight)return;inFlight=true;try{const r=await bindingsApi.getRun(projectId,draftId,sceneId,runId);if(alive){run.value=r;await reload()}}catch(e){if(alive)error.value=(e as Error).message}finally{inFlight=false}}
async function select(input:{take_id?:string;utterance_id?:string;video_version_id?:string}){if(busy.value)return;busy.value=true;message.value='';try{const latest=await api.draft(projectId,draftId);if(run.value?.selection){run.value=await bindingsApi.selectRun(projectId,draftId,sceneId,runId,{expected_version:latest.version||0,...input})}else if(input.video_version_id){await api.selectSceneVersion(projectId,draftId,sceneId,latest.version||0,input.video_version_id);await refresh()}else if(input.take_id){await bindingsApi.select(projectId,draftId,sceneId,{expected_version:latest.version||0,take_id:input.take_id,utterance_id:input.utterance_id});await refresh()}await reload()}catch(e){message.value=(e as Error).message}finally{busy.value=false}}
function isSelected(t:RunStep){const take=takes.value.find(x=>x.task_id===t.id);if(!run.value?.selection)return t.kind==='video'?!!versions.value.find(v=>v.task_id===t.id&&draft.value?.selected_versions?.[sceneId]===v.id):!!take&&draft.value?.selected_media?.[t.kind==='image'?`${sceneId}:image`:`${sceneId}:speech:${take.utterance_id}`]===take.id;return t.kind==='image'?!!take&&run.value?.selection?.image_take_id===take.id:t.kind==='speech'?!!take&&run.value?.selection?.speech_take_ids?.[take.utterance_id||'']===take.id:!!versions.value.find(v=>v.task_id===t.id&&v.id===run.value?.selection?.video_version_id)}
async function choose(t:RunStep){if(t.kind==='video'){const v=versions.value.find(v=>v.task_id===t.id);if(v)await select({video_version_id:v.id})}else{const take=takes.value.find(x=>x.task_id===t.id);if(take)await select({take_id:take.id,utterance_id:take.utterance_id})}}
async function retry(id:string){busy.value=true;try{await api.retryTask(id);await refresh()}catch(e){message.value=(e as Error).message}finally{busy.value=false}}
async function cancel(){busy.value=true;try{run.value=await bindingsApi.cancelRun(projectId,draftId,sceneId,runId);await refresh()}catch(e){message.value=(e as Error).message}finally{busy.value=false}}
async function download(t:RunStep){try{await api.downloadTask(t.id,t.kind==='video'?'video':t.kind==='speech'?'speech':'image')}catch(e){message.value=(e as Error).message}}
onMounted(()=>{void refresh();timer=setInterval(()=>{if(!['completed','cancelled'].includes(run.value?.state||''))void refresh()},4000)});
onBeforeUnmount(()=>{alive=false;clearInterval(timer)});
</script>
<template><main class="shot-workspace"><nav class="shot-breadcrumb"><RouterLink :to="`${base}/shots`">分镜列表</RouterLink><span>›</span><RouterLink :to="`${base}/shots/${encodeURIComponent(sceneId)}`">分镜详情</RouterLink><span>› 任务详情</span></nav><p v-if="error||message" role="alert">{{error||message}}</p><template v-if="run"><header class="shot-page-heading"><div><h1>制作任务详情</h1><small>{{run.id}} · {{run.created_at?new Date(run.created_at).toLocaleString():'历史记录'}}</small></div><RouterLink :to="`${base}?tab=video`">前往成片</RouterLink><button v-if="!['completed','cancelled','awaiting_composition'].includes(run.state)" :disabled="busy" @click="cancel">取消制作任务</button></header><section v-if="!directVideo" class="shot-task-structure"><h2>{{directVideo?'视频状态':'制作流程'}}</h2><GenerationRunStages :run="run" /><p v-if="run.error" role="alert">{{run.error}}</p><p v-if="run.state==='awaiting_selection'">请选用本任务的分镜图及每句配音，随后继续生成视频。</p><p v-if="run.state==='awaiting_video_selection'">视频已生成，请预览后选用。</p><p v-if="run.state==='awaiting_composition'">视频已选用，整片合成请前往成片页面。</p></section><section class="shot-task-structure" aria-label="生成记录"><h2>{{directVideo?'视频内容':'生成记录与视频内容'}}</h2><template v-if="directVideo"><GenerationRunStages :run="run" /><p v-if="run.error" role="alert">{{run.error}}</p><p v-if="run.state==='awaiting_composition'">视频已选用，可前往成片页面合成。</p></template><p v-if="!steps.length">任务准备中…</p><article v-for="t in steps" :key="t.id" class="run-step"><header><h3>{{kindLabels[t.kind]||t.kind}}</h3><span>{{statusLabels[t.status]||t.status}} {{t.progress||0}}%</span></header><div v-if="t.kind==='video'&&(t.status==='queued'||t.status==='running')" class="run-video-progress"><strong>{{t.status==='queued'?'视频等待生成':'正在生成视频'}}</strong><progress :value="t.progress||0" max="100" aria-label="视频生成进度"/><span>完成后在这里预览和下载</span></div><p v-if="t.error" role="alert">{{t.error}}</p><template v-if="t.status==='succeeded'&&t.result_url"><ShotPreview v-if="t.kind==='video'||t.kind==='image'" :title="kindLabels[t.kind]" :url="t.kind==='video'?api.mediaUrl(t.result_url):undefined" :image="t.kind==='image'?api.mediaUrl(t.result_url):undefined" /><audio v-if="t.kind==='speech'" :src="api.mediaUrl(t.result_url)" controls preload="none" /><div class="shot-list-actions"><button :disabled="busy||isSelected(t)||run.state==='cancelled'" @click="choose(t)">{{isSelected(t)?'已选用':'选用此结果'}}</button><button @click="download(t)">下载{{kindLabels[t.kind]}}</button></div></template><button v-if="t.status==='failed'||t.status==='cancelled'" :disabled="busy||run.state==='cancelled'" @click="retry(t.id)">按原输入重试</button></article></section><section class="shot-task-structure" aria-label="本次生成设定"><h2>本次生成设定</h2><p><span v-if="!directVideo">分镜图模型：{{snapshot?.model_id}} · </span>视频模型：{{run.video_model_id}}</p><p>画幅：{{snapshot?.aspect_ratio}} · {{run.duration_seconds}} 秒 · {{run.resolution}}</p><details><summary>提交时的场景描述与引用素材</summary><p class="snapshot-prompt">{{snapshot?.prompt}}</p><article v-for="e in snapshot?.entities" :key="e.binding_id"><strong>{{e.entity_id}} · v{{e.revision}}</strong><p>{{e.description}}</p><span>{{e.references.length}} 张参考图</span></article></details></section></template></main></template>
